(function () {
    "use strict";
    document.addEventListener('DOMContentLoaded', function () {
        var tagInput = document.getElementById('tagInput');
        var inst = null;
        if (tagInput) {
            try {
                var initFn = (typeof UseBootstrapTag !== 'undefined' && UseBootstrapTag) || window.UseBootstrapTag || window.useBootstrapTag;
                if (typeof initFn === 'function') { inst = initFn(tagInput); }
            } catch (e) { }

            function setRoles() {
                var wrap = tagInput.nextElementSibling;
                if (wrap && wrap.classList && wrap.classList.contains('use-bootstrap-tag')) {
                    wrap.setAttribute('role', 'list');
                    var btns = wrap.querySelectorAll('button');
                    for (var b = 0; b < btns.length; b++) { btns[b].setAttribute('role', 'listitem'); }
                }
            }
            setRoles();
            tagInput.addEventListener('change', setRoles);

            var fileInput = document.getElementById('file');
            if (fileInput) {
                fileInput.addEventListener('change', function () {
                    if (this.files.length > 0) {
                        var file = this.files[0];
                        var nameEl = document.getElementById('original_filename');
                        if (nameEl) { nameEl.value = file.name; }
                        var mimeType = (file.type || '').toLowerCase();
                        var fileName = (file.name || '').toLowerCase();
                        var fileExt = fileName.indexOf('.') !== -1 ? fileName.split('.').pop() : '';
                        var detectedTag = 'other';
                        if (mimeType.indexOf('image/') === 0) detectedTag = 'image';
                        else if (mimeType.indexOf('video/') === 0) detectedTag = 'video';
                        else if (mimeType.indexOf('audio/') === 0) detectedTag = 'audio';
                        else {
                            var imageExts = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp', 'svg'];
                            var videoExts = ['mp4', 'webm', 'ogv', 'ogg', 'mov', 'avi', 'mkv', 'flv', 'wmv'];
                            var audioExts = ['mp3', 'wav', 'oga', 'm4a', 'aac', 'flac', 'wma'];
                            if (imageExts.indexOf(fileExt) !== -1) detectedTag = 'image';
                            else if (videoExts.indexOf(fileExt) !== -1) detectedTag = 'video';
                            else if (audioExts.indexOf(fileExt) !== -1) detectedTag = 'audio';
                        }
                        try {
                            if (inst && typeof inst.addValue === 'function') {
                                var empty = (inst.getValues && inst.getValues().length === 0) || !tagInput.value;
                                if (empty) { inst.addValue(detectedTag); }
                            }
                        } catch (err) { }
                    }
                });
            }

            // Client-side validation
            var SPACE_RE = new RegExp("\\s+", "g");
            var form = tagInput && tagInput.form;
            if (form) {
                form.addEventListener('submit', function (e) {
                    var val = (tagInput.value || '');
                    var parts = val ? val.split(',') : [];
                    var cleaned = [];
                    for (var p = 0; p < parts.length; p++) {
                        var s = parts[p];
                        if (s) {
                            s = s.trim().replace(SPACE_RE, ' ');
                            if (s) cleaned.push(s);
                        }
                    }
                    var set = Object.create(null), unique = [];
                    for (var i = 0; i < cleaned.length; i++) {
                        var t = cleaned[i];
                        var k = t.toLowerCase();
                        if (!set[k]) { set[k] = true; unique.push(t); }
                    }
                    var TAG_RE = /^[^,]+$/;
                    var errMsg = '';
                    if (unique.length > 20) errMsg = 'Muitas tags (max. 20).';
                    if (!errMsg) {
                        for (var j = 0; j < unique.length; j++) {
                            var tt = unique[j];
                            if (tt.length > 32) { errMsg = 'Tag muito longa (max. 32).'; break; }
                            if (!TAG_RE.test(tt)) { errMsg = 'Caracteres inválidos.'; break; }
                        }
                    }
                    if (!errMsg) {
                        var csv = unique.join(',');
                        if (csv.length > 512) errMsg = 'Total muito grande (max. 512 chars).';
                    }
                    if (errMsg) {
                        e.preventDefault();
                        tagInput.classList.add('is-invalid');
                        var fb = tagInput.parentElement.querySelector('.invalid-feedback');
                        if (!fb) fb = tagInput.nextElementSibling;
                        if (fb && fb.classList && fb.classList.contains('invalid-feedback')) {
                            fb.textContent = 'Tags inválidas. ' + errMsg;
                            fb.style.display = 'block';
                        }
                        return;
                    }
                    tagInput.value = unique.join(',');
                    tagInput.classList.remove('is-invalid');
                });
            }
        }
    });
})();